    ax += dt*sp; ay += dt*sp*.45; bx -= dt*sp*.7; by += dt*sp*.3; cx += dt*sp*.23; cy -= dt*sp*.17; t += dt;
    ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0, 0, W, H);
